function applyLanguage(){document.documentElement.lang=lang();document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=I18N[lang()][el.dataset.i18n]||el.textContent);document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>el.placeholder=I18N[lang()][el.dataset.i18nPlaceholder]||el.placeholder);document.querySelectorAll('[data-label-en]').forEach(el=>el.textContent=lang()==='tr'?el.dataset.labelTr:el.dataset.labelEn);if(cloud?.enabled)$('[data-i18n="dataLocation"]').textContent=tx('Operational data is securely stored in your Hamvara cloud workspace.','Operasyon verileri Hamvara bulut çalışma alanınızda güvenle saklanır.')}


async function load(){
  try{state=cloud?.enabled?await cloud.load():JSON.parse(invoke?await invoke('load_state'):localStorage.getItem('hamvara_state')||await (await fetch('initial-data.json')).text())}
  catch(e){state=await (await fetch('initial-data.json')).json();toast(tx('Initial data loaded','Başlangıç verileri yüklendi'))}
  normalize();bind();applyLanguage();renderAll();
}
function normalize(){state.products??=[];state.skus??=[];state.orders??=[];state.receipts??=[];state.exchangeListings??=[];state.boms??={};state.stock??={};state.warehouses??=[];state.settings??={};state.suppliers??=[];state.purchaseRequests??=[];state.purchaseOrders??=[];state.qualityInspections??=[];state.salesOrders??=[];state.financeApprovals??=[];state.shipments??=[];state.settings.currency??='TRY';state.settings.language??='en';state.schemaVersion??=1;const old=state.warehouses.find(w=>w.code==='WH-OT');if(old){old.code='WH-FG';old.name='Product';for(const s of Object.values(state.stock)){s['WH-FG']=(+s['WH-FG']||0)+(+s['WH-OT']||0);delete s['WH-OT']}state.skus.forEach(x=>{if(x.warehouse==='WH-OT')x.warehouse='WH-FG'});Object.values(state.boms).flat().forEach(x=>{if(x.warehouse==='WH-OT')x.warehouse='WH-FG'})}const required=[['WH-RM','Raw Materials'],['WH-PK','Packaging'],['WH-FG','Product'],['WH-QA','Quarantine'],['WH-SF','Shop Floor']];state.warehouses=required.map(([code,name])=>state.warehouses.find(w=>w.code===code)||{code,name});state.receipts.forEach(r=>{if(!r.status){r.status='POSTED';r.qcStatus='ACCEPTED';r.managerStatus='APPROVED';r.targetWarehouse=r.warehouse}});state.appVersion='0.5.1';state.schemaVersion=Math.max(7,+state.schemaVersion||1);const priorities=['NORMAL','URGENT','VERY_URGENT'];state.orders.forEach(o=>{if(!priorities.includes(o.priority))o.priority='NORMAL'})}
function dirty(){clearTimeout(saveTimer);$('#saveState').textContent=I18N[lang()].saving;$('#saveState').className='badge warn';saveTimer=setTimeout(save,600)}
async function save(){
  const payload=JSON.stringify(state);
  try{if(cloud?.enabled)await cloud.save(state);else if(invoke)await invoke('save_state',{payload});else localStorage.setItem('hamvara_state',payload);$('#saveState').textContent=I18N[lang()].saved;$('#saveState').className='badge ok'}catch(e){$('#saveState').textContent='Save failed';$('#saveState').className='badge danger';toast(tx('Save error: ','Kayıt hatası: ')+e)}
}
function toast(t){const x=$('#toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),2500)}
function totalStock(code){return calculateAvailableStock(state.stock[code],state.warehouses)}
function sku(code){return state.skus.find(x=>x.code===code)}
function product(code){return state.products.find(x=>x.code===code)}
function n(v,d=2){return (+v||0).toLocaleString('tr-TR',{maximumFractionDigits:d})}
function input(value,field,type='text',extra=''){const numeric=type==='number';return `<input ${extra} type="${numeric?'text':type}" ${numeric?'inputmode="decimal" data-number="true"':''} data-field="${field}" value="${esc(value)}">`}
const ITEM_TYPES=[['RAW_MATERIAL','Raw Material','Hammadde'],['PACKAGING','Packaging','Ambalaj'],['SEMI_FINISHED','Semi-Finished','Yarı Mamul'],['COMPONENT','Component','Bileşen'],['CONSUMABLE','Consumable','Sarf Malzemesi'],['SERVICE','Service','Hizmet']];
const UNITS=[['ADET','Piece','Adet'],['KG','Kilogram','Kilogram'],['G','Gram','Gram'],['L','Liter','Litre'],['ML','Milliliter','Mililitre'],['M','Meter','Metre'],['M2','Square Meter','Metrekare'],['M3','Cubic Meter','Metreküp'],['PAKET','Pack','Paket'],['RULO','Roll','Rulo'],['KUTU','Box','Kutu']];
function optionSelect(value,field,options){return `<select data-field="${field}">${options.map(([v,en,tr])=>`<option value="${v}" ${v===value?'selected':''}>${tx(en,tr)}</option>`).join('')}</select>`}

function bind(){
  document.addEventListener('input',e=>{const el=e.target.closest?.('[data-number]');if(!el)return;const normalized=normalizeNumericText(el.value);if(normalized!==el.value)el.value=normalized});
  $('#nav').onclick=e=>{const b=e.target.closest('button[data-page]');if(!b)return;document.querySelectorAll('#nav button,.page').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('#'+b.dataset.page).classList.add('active');if(b.dataset.page==='bom'){refreshLists();renderBom()}if(b.dataset.page==='requirements')renderRequirements();if(b.dataset.page==='exchange')renderExchange()};
  $('#productSearch').oninput=renderProducts;$('#exchangeSearch').oninput=renderExchange;$('#addListing').onclick=addExchangeListing;$('#suggestExcess').onclick=suggestExcessListings;$('#skuSearch').oninput=renderSkus;$('#stockSearch').oninput=renderStock;$('#receiptSku').oninput=updateReceiptDescription;$('#postReceipt').onclick=postReceipt;
  $('#addProduct').onclick=()=>{state.products.unshift({code:'NEW-'+Date.now(),name:tx('New Product','Yeni Ürün'),unit:'ADET',active:true,notes:''});dirty();renderProducts();refreshLists()};
  $('#addSku').onclick=()=>{const code='SKU-'+Date.now();state.skus.unshift({code,name:tx('New SKU','Yeni SKU'),type:'',category:'',unit:'ADET',cost:0,warehouse:'WH-RM',supplier:'',leadTime:0,min:0,max:0,active:true});state.stock[code]=Object.fromEntries([...state.warehouses.map(w=>[w.code,0]),['reserved',0]]);dirty();renderSkus();refreshLists()};
  $('#addOrder').onclick=()=>{state.orders.push({id:crypto.randomUUID?.()||String(Date.now()),orderNo:'ORD-'+String(state.orders.length+1).padStart(4,'0'),date:new Date().toISOString().slice(0,10),customer:'',productCode:'',qty:0,due:'',priority:'NORMAL',notes:''});dirty();renderOrders()};
  $('#addSupplier').onclick=addSupplier;$('#addPr').onclick=addPurchaseRequest;$('#addPo').onclick=addPurchaseOrder;$('#addInspection').onclick=addInspection;$('#addSalesOrder').onclick=addSalesOrder;$('#addFinanceApproval').onclick=addFinanceApproval;$('#addShipment').onclick=addShipment;
  $('#language').onchange=e=>{state.settings.language=e.target.value;dirty();applyLanguage();renderAll()};$('#bomProduct').onchange=renderBom;$('#addBomItem').onclick=addBomItem;$('#saveBom').onclick=saveBom;
  $('#backupBtn').onclick=async()=>{await save();try{const p=invoke?await invoke('create_backup',{payload:JSON.stringify(state)}):tx('Browser version','Tarayıcı sürümü');toast(tx('Backup created: ','Yedek oluşturuldu: ')+p)}catch(e){toast(String(e))}};
  $('#exportBtn').onclick=()=>exportText('hamvara_data.json',JSON.stringify(state,null,2),'application/json');
  $('#importFile').onchange=async e=>{try{const x=JSON.parse(await e.target.files[0].text());if(!x.products||!x.skus)throw Error(tx('Invalid file structure','Geçersiz dosya yapısı'));state=x;normalize();dirty();renderAll();toast(tx('Data imported','Veriler içe aktarıldı'))}catch(err){toast(tx('Error: ','Hata: ')+err.message)}};
  $('#exportRequirements').onclick=exportRequirements;
  document.querySelectorAll('[data-template]').forEach(b=>b.onclick=()=>downloadImportTemplate(b.dataset.template));
  document.querySelectorAll('input[data-import]').forEach(i=>i.onchange=async e=>{const file=e.target.files?.[0];e.target.value='';if(file)await prepareImport(i.dataset.import,file)});
  $('#closeImportReview').onclick=$('#cancelImport').onclick=closeImportReview;$('#postImport').onclick=postValidatedImport;
  $('#warehouseRoot').onclick=()=>$('#warehouseBranches').hidden=!$('#warehouseBranches').hidden;
  $('#warehouseBranches').onclick=e=>{const b=e.target.closest('[data-warehouse]');if(!b)return;selectedWarehouse=b.dataset.warehouse;renderWarehouseBranches();renderStock()};
  $('#saveSettings').onclick=()=>{state.company=$('#companyName').value;state.settings.currency=$('#currency').value;state.settings.language=$('#language').value;dirty();applyLanguage();renderAll();toast(tx('Settings saved','Ayarlar kaydedildi'))};
}
function bindTable(table,collection,rerender){
  table.onchange=e=>{const el=e.target.closest('[data-field]');if(!el)return;const row=collection[+el.closest('tr').dataset.index];let v=el.dataset.number?parseLocalizedNumber(el.value):el.value;row[el.dataset.field]=v;dirty();rerender?.()};
  table.onclick=e=>{const b=e.target.closest('[data-delete]');if(!b)return;collection.splice(+b.closest('tr').dataset.index,1);dirty();rerender();refreshLists()};
}
function renderAll(){refreshLists();renderWarehouseBranches();renderDashboard();renderProducts();renderSkus();renderStock();renderReceipts();renderBom();renderOrders();renderProcurement();renderQuality();renderSales();renderShipping();renderExchange();$('#companyName').value=state.company||'';$('#currency').value=state.settings.currency||'TRY';$('#language').value=lang();if(!$('#receiptDate').value)$('#receiptDate').value=new Date().toISOString().slice(0,10);$('#schemaVersion').textContent=state.schemaVersion}
function refreshLists(){
  $('#skuOptions').innerHTML=state.skus.map(x=>`<option value="${esc(x.code)}">${esc(x.name)}</option>`).join('');
  $('#productOptions').innerHTML=state.products.map(x=>`<option value="${esc(x.code)}">${esc(x.name)}</option>`).join('');
  const old=$('#bomProduct').value;$('#bomProduct').innerHTML=state.products.map(x=>`<option value="${esc(x.code)}">${esc(x.code)} — ${esc(x.name)}</option>`).join('');$('#bomProduct').value=old&&state.products.some(x=>x.code===old)?old:state.products[0]?.code||'';
  const rw=$('#receiptWarehouse'),rwOld=rw.value;rw.innerHTML=state.warehouses.filter(w=>w.code!=='WH-QA').map(w=>`<option value="${w.code}">${warehouseName(w)}</option>`).join('');if(rwOld)rw.value=rwOld;
}
function compute(){
  const remaining=Object.fromEntries(state.skus.map(x=>[x.code,totalStock(x.code)])),details=[],summaries=[];
  for(const o of sortOrdersForAllocation(state.orders)){let ok=0,missing=0,incomplete=0,defined=0,first='';const lines=state.boms[o.productCode]||[];
    for(const l of lines){if(!l.sku)continue;defined++;const qty=Number(l.qty),need=Number(o.qty||0)*(Number.isFinite(qty)?qty:0),available=remaining[l.sku]||0;let status='SUFFICIENT',shortage=0;
      if(!Number.isFinite(qty)){status='ENTER FACTOR';incomplete++;first||=l.sku}
      else if(available<need){status='SHORTAGE';shortage=need-available;missing++;first||=l.sku;remaining[l.sku]=0}
      else{ok++;remaining[l.sku]=available-need}
      details.push({orderNo:o.orderNo,productCode:o.productCode,productName:product(o.productCode)?.name||'',orderQty:+o.qty||0,sku:l.sku,name:sku(l.sku)?.name||l.name,warehouse:l.warehouse||sku(l.sku)?.warehouse||'',factor:l.qty,need,available,shortage,status});
    }
    const result=!o.productCode?'EMPTY':incomplete?'INCOMPLETE BOM':missing?'NOT PRODUCIBLE':'PRODUCIBLE';summaries.push({order:o,defined,ok,missing,incomplete,first,result});
  }return {details,summaries};
}
function renderDashboard(){const c=compute(),critical=state.skus.filter(x=>totalStock(x.code)<(+x.min||0)).length,missing=c.details.filter(x=>x.status==='SHORTAGE').length,good=c.summaries.filter(x=>x.result==='PRODUCIBLE').length,live=state.exchangeListings.filter(x=>x.status==='ACTIVE'||x.status==='NEGOTIATION').length;
  $('#kpis').innerHTML=[[tx('Products','Ürünler'),state.products.length],['SKU',state.skus.length],[tx('Critical Items','Kritik Kalemler'),critical],[tx('Order Shortages','Sipariş Eksikleri'),missing],[tx('Producible Orders','Üretilebilir Siparişler'),good],[tx('Live Exchange Listings','Aktif Borsa İlanları'),live]].map(x=>`<div class="kpi">${x[0]}<b>${n(x[1],0)}</b></div>`).join('');
  const alerts=[];if(critical)alerts.push(tx(`${critical} item(s) below minimum stock.`,`${critical} kalem minimum stok altında.`));if(missing)alerts.push(tx(`${missing} order item shortage(s).`,`${missing} sipariş kaleminde eksik var.`));const inc=c.summaries.filter(x=>x.incomplete).length;if(inc)alerts.push(tx(`${inc} order(s) have incomplete BOM factors.`,`${inc} siparişte reçete katsayısı eksik.`));const iqc=state.qualityInspections.filter(x=>x.result==='PENDING').length,manager=state.receipts.filter(x=>x.status==='PENDING_MANAGER').length,finance=state.financeApprovals.filter(x=>x.status==='PENDING').length,ship=state.shipments.filter(x=>x.shippingRelease==='BLOCKED').length;if(iqc)alerts.push(tx(`${iqc} quality inspection(s) are pending.`,`${iqc} kalite kontrolü bekliyor.`));if(manager)alerts.push(tx(`${manager} receipt(s) await manager approval.`,`${manager} kabul yönetici onayı bekliyor.`));if(finance)alerts.push(tx(`${finance} financial approval(s) are pending.`,`${finance} finans onayı bekliyor.`));if(ship)alerts.push(tx(`${ship} shipment(s) are blocked by process gates.`,`${ship} sevkiyat süreç kontrolünde engelli.`));$('#alerts').innerHTML=alerts.length?alerts.map(x=>`<p class="status-warn">${x}</p>`).join(''):`<p class="status-ok">${tx('No action required.','İşlem gerekmiyor.')}</p>`;
}
function renderProducts(){const q=$('#productSearch').value.toLowerCase(),rows=state.products.map((x,i)=>({x,i})).filter(o=>(o.x.code+' '+o.x.name).toLowerCase().includes(q)).slice(0,500);$('#productTable').innerHTML=`<thead><tr><th>${tx('Product Code','Ürün Kodu')}</th><th>${tx('Description','Açıklama')}</th><th>${tx('Unit','Birim')}</th><th>${tx('Notes','Notlar')}</th><th></th></tr></thead><tbody>`+rows.map(o=>`<tr data-index="${o.i}"><td>${input(o.x.code,'code')}</td><td>${input(o.x.name,'name')}</td><td>${optionSelect(o.x.unit,'unit',UNITS)}</td><td>${input(o.x.notes,'notes')}</td><td><button data-delete class="delete">${tx('Delete','Sil')}</button></td></tr>`).join('')+'</tbody>';bindTable($('#productTable'),state.products,()=>{renderProducts();refreshLists();renderBom()})}
function renderSkus(){const q=$('#skuSearch').value.toLowerCase(),rows=state.skus.map((x,i)=>({x,i})).filter(o=>(o.x.code+' '+o.x.name).toLowerCase().includes(q)).slice(0,700);$('#skuTable').innerHTML=`<thead><tr><th>SKU</th><th>${tx('Description','Açıklama')}</th><th>${tx('Type','Tür')}</th><th>${tx('Unit','Birim')}</th><th>${tx('Cost','Maliyet')}</th><th>${tx('Main Warehouse','Ana Depo')}</th><th>Min</th><th>Max</th><th></th></tr></thead><tbody>`+rows.map(o=>`<tr data-index="${o.i}"><td>${input(o.x.code,'code')}</td><td>${input(o.x.name,'name')}</td><td>${optionSelect(o.x.type,'type',ITEM_TYPES)}</td><td>${optionSelect(o.x.unit,'unit',UNITS)}</td><td>${input(o.x.cost,'cost','number','step="0.0001"')}</td><td>${warehouseSelect(o.x.warehouse,'warehouse')}</td><td>${input(o.x.min,'min','number')}</td><td>${input(o.x.max,'max','number')}</td><td><button data-delete class="delete">${tx('Delete','Sil')}</button></td></tr>`).join('')+'</tbody>';bindTable($('#skuTable'),state.skus,()=>{renderSkus();refreshLists();renderBom();updateReceiptDescription()})}
function warehouseName(w){const names={'WH-RM':['Raw Materials','Hammadde'],'WH-PK':['Packaging','Ambalaj'],'WH-FG':['Product','Mamul Ürün'],'WH-QA':['Quarantine','Karantina'],'WH-SF':['Shop Floor','Üretim Alanı']};return names[w.code]?tx(...names[w.code]):w.name}function warehouseSelect(v,field){return `<select data-field="${field}">${state.warehouses.map(w=>`<option value="${w.code}" ${w.code===v?'selected':''}>${warehouseName(w)}</option>`).join('')}</select>`}
function renderWarehouseBranches(){if(!state.warehouses.some(w=>w.code===selectedWarehouse))selectedWarehouse=state.warehouses[0]?.code||'WH-RM';$('#warehouseBranches').innerHTML=state.warehouses.map(w=>`<button type="button" data-warehouse="${w.code}" class="${w.code===selectedWarehouse?'active':''}">${warehouseName(w)}</button>`).join('')}
function renderStock(){const q=$('#stockSearch').value.toLowerCase(),w=state.warehouses.find(x=>x.code===selectedWarehouse)||state.warehouses[0],rows=state.skus.filter(x=>(x.code+' '+x.name).toLowerCase().includes(q)).slice(0,800);$('#stockTable').innerHTML=`<thead><tr><th>SKU</th><th>${tx('Description','Açıklama')}</th><th>${warehouseName(w)}</th><th>${tx('Reserved','Rezerve')}</th><th>${tx('Total Available','Toplam Kullanılabilir')}</th><th>${tx('Status','Durum')}</th></tr></thead><tbody>`+rows.map(x=>{const s=state.stock[x.code]||{};return `<tr data-code="${esc(x.code)}"><td>${esc(x.code)}</td><td>${esc(x.name)}</td><td>${input(s[w.code]||0,w.code,'number','min="0" step="any"')}</td><td>${input(s.reserved||0,'reserved','number','min="0" step="any"')}</td><td>${n(totalStock(x.code),6)}</td><td class="${totalStock(x.code)<(+x.min||0)?'status-bad':'status-ok'}">${totalStock(x.code)<(+x.min||0)?tx('CRITICAL','KRİTİK'):tx('NORMAL','NORMAL')}</td></tr>`}).join('')+'</tbody>';
  $('#stockTable').onchange=e=>{const el=e.target.closest('[data-field]');if(!el)return;const code=el.closest('tr').dataset.code;state.stock[code]??={};state.stock[code][el.dataset.field]=parseLocalizedNumber(el.value)||0;dirty();renderDashboard()}
}

function updateReceiptDescription(){const x=sku($('#receiptSku').value);$('#receiptDescription').value=x?.name||''}
function postReceipt(){
  const code=$('#receiptSku').value.trim(),x=sku(code),warehouse=$('#receiptWarehouse').value,qty=parseLocalizedNumber($('#receiptQty').value);
  if(!x){toast(tx('Select a valid SKU.','Geçerli bir SKU seçin.'));return}
  if(!warehouse||warehouse==='WH-QA'||!state.warehouses.some(w=>w.code===warehouse)){toast(tx('Select a destination warehouse.','Bir hedef depo seçin.'));return}
  if(!Number.isFinite(qty)||qty<=0){toast(tx('Quantity must be greater than zero.','Miktar sıfırdan büyük olmalıdır.'));return}
  const reference=$('#receiptReference').value.trim()||'GR-'+String(state.receipts.length+1).padStart(5,'0');
  const receiptId=crypto.randomUUID?.()||String(Date.now()),inspectionId=crypto.randomUUID?.()||receiptId+'-qc';
  queueReceiptForApproval(state,{id:receiptId,inspectionId,inspectionNo:id('IQC',state.qualityInspections),date:$('#receiptDate').value||new Date().toISOString().slice(0,10),reference,sku:code,description:x.name||'',targetWarehouse:warehouse,qty,supplier:$('#receiptSupplier').value.trim(),notes:$('#receiptNotes').value.trim(),transactionType:'GOODS_RECEIPT_QUARANTINE',postedAt:new Date().toISOString()});
  dirty();$('#receiptQty').value='';$('#receiptReference').value='';$('#receiptSupplier').value='';$('#receiptNotes').value='';renderReceipts();renderStock();renderQuality();renderDashboard();toast(tx('Receipt submitted to quarantine for QC.','Kabul QC için karantinaya gönderildi.'))
}
function renderReceipts(){
  updateReceiptDescription();
  $('#receiptTable').innerHTML=`<thead><tr><th>${tx('Date','Tarih')}</th><th>${tx('Reference','Referans')}</th><th>SKU</th><th>${tx('Destination','Hedef')}</th><th>${tx('Quantity','Miktar')}</th><th>QC</th><th>${tx('Manager','Yönetici')}</th><th>${tx('Status','Durum')}</th><th>NCR</th><th>${tx('Action','İşlem')}</th></tr></thead><tbody>`+state.receipts.map(r=>`<tr data-receipt-id="${esc(r.id)}"><td>${esc(r.date)}</td><td>${esc(r.reference)}</td><td>${esc(r.sku)}</td><td>${esc(warehouseName(state.warehouses.find(w=>w.code===(r.targetWarehouse||r.warehouse))||{code:r.targetWarehouse||r.warehouse,name:r.targetWarehouse||r.warehouse}))}</td><td>${n(r.qty,4)}</td><td>${chip(r.qcStatus||'ACCEPTED')}</td><td>${chip(r.managerStatus||'APPROVED')}</td><td>${chip(r.status||'POSTED')}</td><td>${esc(r.ncrNo||'—')}</td><td>${r.status==='PENDING_MANAGER'?`<button class="gate-action" data-manager-approve>${tx('Manager approve','Yönetici onayı')}</button><button class="delete" data-manager-reject>${tx('Reject','Reddet')}</button>`:'—'}</td></tr>`).join('')+'</tbody>';
  $('#receiptTable').onclick=e=>{const row=e.target.closest('tr[data-receipt-id]');if(!row)return;if(e.target.closest('[data-manager-approve]'))managerReceiptDecision(row.dataset.receiptId,true);if(e.target.closest('[data-manager-reject]'))managerReceiptDecision(row.dataset.receiptId,false)}
}
function managerReceiptDecision(receiptId,approved){try{const ncrNo=approved?'':id('NCR',state.qualityInspections.filter(x=>x.ncrNo));const receipt=applyManagerReceiptDecision(state,receiptId,approved,ncrNo);const inspection=state.qualityInspections.find(x=>x.receiptId===receiptId);const po=state.purchaseOrders.find(x=>x.poNo===inspection?.reference);if(po)po.status=approved?'ACCEPTED':'REJECTED';dirty();renderAll();toast(approved?tx('Manager approved; stock posted to destination.','Yönetici onayladı; stok hedef depoya işlendi.'):tx('Manager rejected; stock remains in quarantine under NCR.','Yönetici reddetti; stok NCR ile karantinada kaldı.'))}catch(e){toast(e.message)}}
function renderBom(){const code=$('#bomProduct').value||state.products[0]?.code;if(!code){$('#bomInfo').textContent=tx('Create a product first, then add BOM items.','Önce bir ürün oluşturun, ardından reçete kalemlerini ekleyin.');$('#bomTable').innerHTML='';$('#addBomItem').disabled=true;return}const lines=[...(state.boms[code]||[])];const p=product(code);$('#bomInfo').textContent=`${code} — ${p?.name||''} | Defined items / Tanımlı kalem: ${lines.filter(x=>x.sku).length} / 20`;
  $('#addBomItem').disabled=lines.length>=20;
  $('#bomTable').innerHTML=`<thead><tr><th>No.</th><th>SKU</th><th>${tx('Description','Açıklama')}</th><th>${tx('Source Warehouse','Kaynak Depo')}</th><th>${tx('Usage Quantity','Kullanım Miktarı')}</th><th>${tx('Stock','Stok')}</th><th></th></tr></thead><tbody>`+lines.map((l,i)=>`<tr data-slot="${i}"><td>${i+1}</td><td><input data-bom="sku" list="skuOptions" value="${esc(l.sku)}"></td><td>${esc(sku(l.sku)?.name||l.name||'')}</td><td>${warehouseSelect(l.warehouse||sku(l.sku)?.warehouse||'WH-RM','warehouse').replace('data-field','data-bom')}</td><td><input data-bom="qty" data-number="true" type="text" min="0.000001" step="any" inputmode="decimal" value="${l.qty??''}"></td><td>${n(totalStock(l.sku),6)}</td><td><button type="button" data-bom-delete class="delete">${tx('Delete','Sil')}</button></td></tr>`).join('')+'</tbody>';
  $('#bomTable').onchange=e=>{const el=e.target.closest('[data-bom]');if(!el)return;const i=+el.closest('tr').dataset.slot;if(el.dataset.bom==='qty'){const value=el.value===''?null:parseLocalizedNumber(el.value);if(value!==null&&(!Number.isFinite(value)||value<=0)){toast(tx('Usage quantity must be greater than zero.','Kullanım miktarı sıfırdan büyük olmalıdır.'));renderBom();return}lines[i].qty=value}else lines[i][el.dataset.bom]=el.value;if(el.dataset.bom==='sku'){const x=sku(el.value);lines[i].name=x?.name||'';lines[i].warehouse=x?.warehouse||'WH-RM'}state.boms[code]=lines;dirty();renderBom()};
  $('#bomTable').onclick=e=>{const b=e.target.closest('[data-bom-delete]');if(!b)return;lines.splice(+b.closest('tr').dataset.slot,1);state.boms[code]=lines;dirty();renderBom()}
}
function addBomItem(){const code=$('#bomProduct').value||state.products[0]?.code;if(!code)return;const lines=state.boms[code]??=[];if(lines.length>=20){toast(tx('Maximum 20 items','En fazla 20 kalem'));return}lines.push({sku:'',name:'',warehouse:'WH-RM',qty:null});state.boms[code]=lines;dirty();renderBom()}
function saveBom(){const code=$('#bomProduct').value;state.boms[code]=(state.boms[code]||[]).filter(x=>x.sku);dirty();renderBom();toast(tx('Product BOM saved','Ürün reçetesi kaydedildi'))}
function renderOrders(){$('#orderTable').innerHTML=`<thead><tr><th>${tx('Order No.','Sipariş No.')}</th><th>${tx('Date','Tarih')}</th><th>${tx('Customer','Müşteri')}</th><th>${tx('Product Code','Ürün Kodu')}</th><th>${tx('Description','Açıklama')}</th><th>${tx('Quantity','Miktar')}</th><th>${tx('Due Date','Termin')}</th><th>${tx('Priority','Öncelik')}</th><th>${tx('Notes','Notlar')}</th><th></th></tr></thead><tbody>`+state.orders.map((o,i)=>`<tr data-index="${i}"><td>${input(o.orderNo,'orderNo')}</td><td>${input(o.date,'date','date')}</td><td>${input(o.customer,'customer')}</td><td><input data-field="productCode" list="productOptions" value="${esc(o.productCode)}"></td><td>${esc(product(o.productCode)?.name||'')}</td><td>${input(o.qty,'qty','number','step="0.0001"')}</td><td>${input(o.due,'due','date')}</td><td><select data-field="priority"><option value="NORMAL" ${o.priority==='NORMAL'?'selected':''}>${tx('Normal','Normal')}</option><option value="URGENT" ${o.priority==='URGENT'?'selected':''}>${tx('Urgent','Acil')}</option><option value="VERY_URGENT" ${o.priority==='VERY_URGENT'?'selected':''}>${tx('Very Urgent','Çok Acil')}</option></select></td><td>${input(o.notes,'notes')}</td><td><button data-delete class="delete">${tx('Delete','Sil')}</button></td></tr>`).join('')+'</tbody>';bindTable($('#orderTable'),state.orders,renderOrders)}
function statusLabel(v){const x={'PRODUCIBLE':['Producible','Üretilebilir'],'NOT PRODUCIBLE':['Not Producible','Üretilemez'],'INCOMPLETE BOM':['Incomplete BOM','Eksik Reçete'],'EMPTY':['Empty','Boş'],'SUFFICIENT':['Sufficient','Yeterli'],'SHORTAGE':['Shortage','Eksik'],'ENTER FACTOR':['Enter Factor','Katsayı Gir']}[v];return x?tx(...x):v}
function renderRequirements(){const c=compute();$('#orderSummary').innerHTML=c.summaries.map(s=>`<div class="order-card ${s.result==='NOT PRODUCIBLE'?'bad':s.result==='INCOMPLETE BOM'?'warn':''}"><b>${esc(s.order.orderNo)} — ${esc(product(s.order.productCode)?.name||s.order.productCode)}</b><p>${statusLabel(s.result)}</p><small>${s.defined} ${tx('defined','tanımlı')} | ${s.ok} ${tx('available','mevcut')} | ${s.missing} ${tx('shortage','eksik')} ${s.first?'| '+tx('Issue','Sorun')+': '+esc(s.first):''}</small></div>`).join('');$('#requirementTable').innerHTML=`<thead><tr><th>${tx('Order','Sipariş')}</th><th>${tx('Product','Ürün')}</th><th>SKU</th><th>${tx('Description','Açıklama')}</th><th>${tx('Warehouse','Depo')}</th><th>${tx('Factor','Katsayı')}</th><th>${tx('Required','İhtiyaç')}</th><th>${tx('Available','Mevcut')}</th><th>${tx('Shortage','Eksik')}</th><th>${tx('Status','Durum')}</th></tr></thead><tbody>`+c.details.map(x=>`<tr><td>${esc(x.orderNo)}</td><td>${esc(x.productCode)}</td><td>${esc(x.sku)}</td><td>${esc(x.name)}</td><td>${esc(x.warehouse)}</td><td>${x.factor??'—'}</td><td>${n(x.need,4)}</td><td>${n(x.available,4)}</td><td>${n(x.shortage,4)}</td><td class="${x.status==='SUFFICIENT'?'status-ok':x.status==='SHORTAGE'?'status-bad':'status-warn'}" >${statusLabel(x.status)}</td></tr>`).join('')+'</tbody>'}

function id(prefix,list){return prefix+'-'+String(list.length+1).padStart(4,'0')}
function selectValues(value,field,values){return `<select data-field="${field}">${values.map(v=>`<option value="${v}" ${v===value?'selected':''}>${v.replaceAll('_',' ')}</option>`).join('')}</select>`}
function chip(value){const good=['APPROVED','ACCEPTED','RELEASED','SHIPPED','CLOSED','MATCHED'].includes(value),bad=['REJECTED','BLOCKED','OVERDUE'].includes(value),warn=['PENDING','CONDITIONAL','QUARANTINE','DRAFT'].includes(value);return `<span class="status-chip ${good?'ok':bad?'bad':warn?'warn':'neutral'}">${esc(String(value||'—').replaceAll('_',' '))}</span>`}

function addSupplier(){state.suppliers.unshift({id:crypto.randomUUID?.()||String(Date.now()),code:id('SUP',state.suppliers),name:'',approved:false,rating:80,paymentTerms:'30 DAYS',leadTime:7,notes:''});dirty();renderProcurement()}
function addPurchaseRequest(){state.purchaseRequests.unshift({id:crypto.randomUUID?.()||String(Date.now()),prNo:id('PR',state.purchaseRequests),date:new Date().toISOString().slice(0,10),requester:'',sku:'',qty:0,needDate:'',priority:'NORMAL',budgetStatus:'PENDING',status:'DRAFT'});dirty();renderProcurement()}
function addPurchaseOrder(){state.purchaseOrders.unshift({id:crypto.randomUUID?.()||String(Date.now()),poNo:id('PO',state.purchaseOrders),prNo:'',supplierCode:'',sku:'',qty:0,unitPrice:0,dueDate:'',status:'DRAFT',grnNo:'',invoiceNo:'',received:false});dirty();renderProcurement()}
function renderProcurement(){
  const approved=state.suppliers.filter(x=>x.approved).length,openPr=state.purchaseRequests.filter(x=>x.status!=='CLOSED').length,openPo=state.purchaseOrders.filter(x=>!['MATCHED','CLOSED'].includes(x.status)).length,quarantine=state.purchaseOrders.filter(x=>x.status==='QUARANTINE').length;
  $('#procurementKpis').innerHTML=[[tx('Approved Suppliers','Onaylı Tedarikçi'),approved],[tx('Open PR','Açık PR'),openPr],[tx('Open PO','Açık PO'),openPo],[tx('Awaiting IQC','IQC Bekleyen'),quarantine]].map(x=>`<div class="kpi">${x[0]}<b>${n(x[1],0)}</b></div>`).join('');
  $('#supplierTable').innerHTML='<thead><tr><th>Code</th><th>Name</th><th>ASL</th><th>Rating</th><th>Terms</th><th>Lead days</th><th></th></tr></thead><tbody>'+state.suppliers.map((x,i)=>`<tr data-index="${i}"><td>${input(x.code,'code')}</td><td>${input(x.name,'name')}</td><td><input data-field="approved" type="checkbox" ${x.approved?'checked':''}></td><td>${input(x.rating,'rating','number','min="0" max="100"')}</td><td>${input(x.paymentTerms,'paymentTerms')}</td><td>${input(x.leadTime,'leadTime','number','min="0"')}</td><td><button data-delete class="delete">Delete</button></td></tr>`).join('')+'</tbody>';
  $('#supplierTable').onchange=e=>processEdit(e,state.suppliers,renderProcurement);$('#supplierTable').onclick=e=>processDelete(e,state.suppliers,renderProcurement);
  $('#prTable').innerHTML='<thead><tr><th>PR</th><th>Date</th><th>Requester</th><th>SKU</th><th>Qty</th><th>Need</th><th>Priority</th><th>Budget</th><th>Status</th><th></th></tr></thead><tbody>'+state.purchaseRequests.map((x,i)=>`<tr data-index="${i}"><td>${input(x.prNo,'prNo')}</td><td>${input(x.date,'date','date')}</td><td>${input(x.requester,'requester')}</td><td><input data-field="sku" list="skuOptions" value="${esc(x.sku)}"></td><td>${input(x.qty,'qty','number','min="0" step="any"')}</td><td>${input(x.needDate,'needDate','date')}</td><td>${selectValues(x.priority,'priority',['NORMAL','URGENT','VERY_URGENT'])}</td><td>${selectValues(x.budgetStatus,'budgetStatus',['PENDING','APPROVED','REJECTED'])}</td><td>${selectValues(x.status,'status',['DRAFT','APPROVED','CLOSED'])}</td><td><button data-delete class="delete">Delete</button></td></tr>`).join('')+'</tbody>';
  $('#prTable').onchange=e=>processEdit(e,state.purchaseRequests,renderProcurement);$('#prTable').onclick=e=>processDelete(e,state.purchaseRequests,renderProcurement);
  $('#poTable').innerHTML='<thead><tr><th>PO</th><th>PR</th><th>Supplier</th><th>SKU</th><th>Qty</th><th>Price</th><th>Due</th><th>GRN</th><th>Invoice</th><th>Status</th><th>Gate</th><th></th></tr></thead><tbody>'+state.purchaseOrders.map((x,i)=>`<tr data-index="${i}"><td>${input(x.poNo,'poNo')}</td><td>${input(x.prNo,'prNo')}</td><td>${input(x.supplierCode,'supplierCode')}</td><td><input data-field="sku" list="skuOptions" value="${esc(x.sku)}"></td><td>${input(x.qty,'qty','number','min="0" step="any"')}</td><td>${input(x.unitPrice,'unitPrice','number','min="0" step=".01"')}</td><td>${input(x.dueDate,'dueDate','date')}</td><td>${input(x.grnNo,'grnNo')}</td><td>${input(x.invoiceNo,'invoiceNo')}</td><td>${chip(x.status)}</td><td><button class="gate-action" data-po-action>${x.status==='DRAFT'?'Approve PO':x.status==='APPROVED'?'Receive to QA':x.status==='QUARANTINE'?'Await IQC':'Check match'}</button></td><td><button data-delete class="delete">Delete</button></td></tr>`).join('')+'</tbody>';
  $('#poTable').onchange=e=>processEdit(e,state.purchaseOrders,renderProcurement);$('#poTable').onclick=e=>{const row=e.target.closest('tr[data-index]');if(!row)return;const i=+row.dataset.index;if(e.target.closest('[data-delete]')){state.purchaseOrders.splice(i,1);dirty();renderProcurement();return}if(e.target.closest('[data-po-action]'))advancePurchaseOrder(i)};
}
function advancePurchaseOrder(i){const po=state.purchaseOrders[i],supplier=state.suppliers.find(x=>x.code===po.supplierCode),pr=state.purchaseRequests.find(x=>x.prNo===po.prNo);if(po.status==='DRAFT'){if(!supplier?.approved){toast(tx('Blocked: supplier is not approved in ASL.','Engellendi: tedarikçi ASL listesinde onaylı değil.'));return}if(!pr||pr.status!=='APPROVED'||pr.budgetStatus!=='APPROVED'){toast(tx('Blocked: PR and budget must be approved.','Engellendi: PR ve bütçe onaylı olmalıdır.'));return}if(!sku(po.sku)||!(+po.qty>0)){toast(tx('Blocked: valid SKU and quantity required.','Engellendi: geçerli SKU ve miktar gerekli.'));return}po.status='APPROVED'}else if(po.status==='APPROVED'){po.grnNo||=id('GRN',state.receipts);const receiptId=crypto.randomUUID?.()||String(Date.now()),inspectionId=crypto.randomUUID?.()||receiptId+'-qc';queueReceiptForApproval(state,{id:receiptId,inspectionId,inspectionNo:id('IQC',state.qualityInspections),date:new Date().toISOString().slice(0,10),reference:po.grnNo,sku:po.sku,description:sku(po.sku)?.name||'',targetWarehouse:sku(po.sku)?.warehouse||'WH-RM',qty:+po.qty||0,supplier:po.supplierCode,notes:'PO '+po.poNo+' | IQC pending',transactionType:'PURCHASE_GRN_QUARANTINE',postedAt:new Date().toISOString()});const inspection=state.qualityInspections.find(x=>x.id===inspectionId);inspection.reference=po.poNo;po.received=true;po.status='QUARANTINE'}else if(['ACCEPTED','CONDITIONAL','REJECTED'].includes(po.status)){if(po.grnNo&&po.invoiceNo&&po.status==='ACCEPTED')po.status='MATCHED';else toast(tx('Three-way match requires accepted QC, GRN and supplier invoice.','Üçlü eşleştirme için kabul edilmiş QC, GRN ve tedarikçi faturası gerekir.'))}dirty();renderAll()}

function addInspection(){state.qualityInspections.unshift({id:crypto.randomUUID?.()||String(Date.now()),inspectionNo:id('QC',state.qualityInspections),type:'IQC',reference:'',sku:'',qty:0,result:'PENDING',date:new Date().toISOString().slice(0,10),ncrNo:'',disposition:'HOLD',released:false,notes:''});dirty();renderQuality()}
function renderQuality(){const pending=state.qualityInspections.filter(x=>x.result==='PENDING').length,rejected=state.qualityInspections.filter(x=>x.result==='REJECTED').length,ncr=state.qualityInspections.filter(x=>x.ncrNo).length,released=state.qualityInspections.filter(x=>x.stockReleased||(!x.receiptId&&x.released)).length;$('#qualityKpis').innerHTML=[[tx('Pending inspection','Bekleyen kontrol'),pending],[tx('Rejected','Reddedilen'),rejected],['NCR',ncr],[tx('Released stock','Serbest bırakılan'),released]].map(x=>`<div class="kpi">${x[0]}<b>${n(x[1],0)}</b></div>`).join('');$('#qualityTable').innerHTML='<thead><tr><th>Inspection</th><th>Stage</th><th>Reference</th><th>SKU</th><th>Qty</th><th>Date</th><th>Result</th><th>NCR</th><th>Disposition</th><th>Notes</th><th>Gate</th><th></th></tr></thead><tbody>'+state.qualityInspections.map((x,i)=>`<tr data-index="${i}"><td>${input(x.inspectionNo,'inspectionNo')}</td><td>${selectValues(x.type,'type',['IQC','IPQC','FQC','OQC'])}</td><td>${input(x.reference,'reference')}</td><td><input data-field="sku" list="skuOptions" value="${esc(x.sku)}"></td><td>${input(x.qty,'qty','number','min="0" step="any"')}</td><td>${input(x.date,'date','date')}</td><td>${selectValues(x.result,'result',['PENDING','ACCEPTED','CONDITIONAL','REJECTED'])}</td><td>${input(x.ncrNo,'ncrNo')}</td><td>${selectValues(x.disposition,'disposition',['HOLD','REWORK','RETURN_TO_SUPPLIER','SCRAP','USE_AS_IS'])}</td><td>${input(x.notes,'notes')}</td><td><button class="gate-action" data-qc-action ${x.released?'disabled':''}>${x.released?(x.receiptId&&x.result==='ACCEPTED'?'Await manager':'Decision applied'):'Apply decision'}</button></td><td><button data-delete class="delete">Delete</button></td></tr>`).join('')+'</tbody>';$('#qualityTable').onchange=e=>processEdit(e,state.qualityInspections,renderQuality);$('#qualityTable').onclick=e=>{const row=e.target.closest('tr[data-index]');if(!row)return;const i=+row.dataset.index;if(e.target.closest('[data-delete]')){state.qualityInspections.splice(i,1);dirty();renderQuality();return}if(e.target.closest('[data-qc-action]'))applyQualityDecision(i)}}
function applyQualityDecision(i){const q=state.qualityInspections[i];if(q.result==='PENDING'){toast(tx('Select a QC result first.','Önce QC sonucu seçin.'));return}if(q.receiptId){try{const ncrNo=['CONDITIONAL','REJECTED'].includes(q.result)&&!q.ncrNo?id('NCR',state.qualityInspections.filter(x=>x.ncrNo)):q.ncrNo;const receipt=applyReceiptQcDecision(state,q.id,ncrNo);const po=state.purchaseOrders.find(x=>x.poNo===q.reference);if(po&&receipt.status==='HOLD_NCR')po.status=q.result;dirty();renderAll();toast(receipt.status==='PENDING_MANAGER'?tx('QC accepted; manager approval is required before posting.','QC kabul etti; kayıt için yönetici onayı gerekli.'):tx('NCR created; stock remains in quarantine.','NCR oluşturuldu; stok karantinada kalır.'));return}catch(e){toast(e.message);return}}if(['CONDITIONAL','REJECTED'].includes(q.result)&&!q.ncrNo){q.ncrNo=id('NCR',state.qualityInspections.filter(x=>x.ncrNo));toast(tx('NCR created; stock remains in quarantine.','NCR oluşturuldu; stok karantinada kalır.'))}if(q.type==='IQC'&&q.result==='ACCEPTED'&&!q.released){const amount=Math.min(+q.qty||0,+state.stock[q.sku]?.['WH-QA']||0),dest=sku(q.sku)?.warehouse||'WH-RM';if(amount<=0){toast(tx('No matching quarantine stock.','Eşleşen karantina stoku yok.'));return}state.stock[q.sku]['WH-QA']-=amount;state.stock[q.sku][dest]=(+state.stock[q.sku][dest]||0)+amount;q.released=true;const po=state.purchaseOrders.find(x=>x.poNo===q.reference);if(po)po.status='ACCEPTED'}else if(q.type==='FQC'){const order=state.salesOrders.find(x=>x.orderNo===q.reference);if(order){order.qcStatus=q.result;order.status=order.reservedQty&&q.result==='ACCEPTED'&&(order.paymentStatus==='PAID'||order.creditApproved)?'READY_TO_SHIP':order.reservedQty?'RESERVED':'DRAFT'}q.released=true}else if(q.type==='OQC'){const shipment=state.shipments.find(x=>x.shipmentNo===q.reference);if(shipment)shipment.oqcStatus=q.result;q.released=true}else if(q.result!=='ACCEPTED')q.released=true;dirty();renderAll()}

function addSalesOrder(){state.salesOrders.unshift({id:crypto.randomUUID?.()||String(Date.now()),orderNo:id('SO',state.salesOrders),date:new Date().toISOString().slice(0,10),customer:'',sku:'',qty:0,unitPrice:0,dueDate:'',paymentStatus:'PENDING',creditApproved:false,qcStatus:'PENDING',status:'DRAFT',reservedQty:0,notes:''});dirty();renderSales()}
function renderSales(){const draft=state.salesOrders.filter(x=>x.status==='DRAFT').length,reserved=state.salesOrders.filter(x=>x.status==='RESERVED').length,blocked=state.salesOrders.filter(x=>x.status==='BLOCKED').length,ready=state.salesOrders.filter(x=>x.status==='READY_TO_SHIP').length;$('#salesKpis').innerHTML=[[tx('Draft orders','Taslak sipariş'),draft],[tx('Reserved','Rezerve'),reserved],[tx('Blocked','Engelli'),blocked],[tx('Ready to ship','Sevke hazır'),ready]].map(x=>`<div class="kpi">${x[0]}<b>${n(x[1],0)}</b></div>`).join('');$('#salesOrderTable').innerHTML='<thead><tr><th>Sales Order</th><th>Date</th><th>Customer</th><th>Finished SKU</th><th>Qty</th><th>Price</th><th>Due</th><th>Payment</th><th>Credit</th><th>FQC</th><th>Status</th><th>ATP Gate</th><th></th></tr></thead><tbody>'+state.salesOrders.map((x,i)=>`<tr data-index="${i}"><td>${input(x.orderNo,'orderNo')}</td><td>${input(x.date,'date','date')}</td><td>${input(x.customer,'customer')}</td><td><input data-field="sku" list="skuOptions" value="${esc(x.sku)}"></td><td>${input(x.qty,'qty','number','min="0" step="any"')}</td><td>${input(x.unitPrice,'unitPrice','number','min="0" step=".01"')}</td><td>${input(x.dueDate,'dueDate','date')}</td><td>${selectValues(x.paymentStatus,'paymentStatus',['PENDING','PARTIAL','PAID','CREDIT'])}</td><td><input data-field="creditApproved" type="checkbox" ${x.creditApproved?'checked':''}></td><td>${selectValues(x.qcStatus,'qcStatus',['PENDING','ACCEPTED','REJECTED'])}</td><td>${chip(x.status)}</td><td><button class="gate-action" data-sales-action ${x.status==='SHIPPED'?'disabled':''}>${x.status==='DRAFT'||x.status==='BLOCKED'?'Check & reserve':'Recheck gates'}</button></td><td><button data-delete class="delete">Delete</button></td></tr>`).join('')+'</tbody>';$('#salesOrderTable').onchange=e=>processEdit(e,state.salesOrders,renderSales);$('#salesOrderTable').onclick=e=>{const row=e.target.closest('tr[data-index]');if(!row)return;const i=+row.dataset.index;if(e.target.closest('[data-delete]')){releaseReservation(state.salesOrders[i]);state.salesOrders.splice(i,1);dirty();renderSales();return}if(e.target.closest('[data-sales-action]'))reserveSalesOrder(i)}}
function releaseReservation(o){if(!o?.reservedQty)return;state.stock[o.sku]??={};state.stock[o.sku].reserved=Math.max(0,(+state.stock[o.sku].reserved||0)-(+o.reservedQty||0));o.reservedQty=0}
function reserveSalesOrder(i){const o=state.salesOrders[i],available=+state.stock[o.sku]?.['WH-FG']||0,reserved=+state.stock[o.sku]?.reserved||0,own=+o.reservedQty||0,free=available-reserved+own;releaseReservation(o);if(!sku(o.sku)||!(+o.qty>0)||free<+o.qty){o.status='BLOCKED';toast(tx('Blocked: insufficient finished-goods stock.','Engellendi: mamul stok yetersiz.'));dirty();renderAll();return}state.stock[o.sku]??={};state.stock[o.sku].reserved=(+state.stock[o.sku].reserved||0)+(+o.qty||0);o.reservedQty=+o.qty||0;o.status=o.qcStatus==='ACCEPTED'&&(o.paymentStatus==='PAID'||o.creditApproved)?'READY_TO_SHIP':'RESERVED';dirty();renderAll()}

function addFinanceApproval(){state.financeApprovals.unshift({id:crypto.randomUUID?.()||String(Date.now()),approvalNo:id('FIN',state.financeApprovals),type:'SALES_RELEASE',reference:'',amount:0,documentMatch:false,qcApproved:false,creditApproved:false,status:'PENDING',notes:''});dirty();renderShipping()}
function addShipment(){state.shipments.unshift({id:crypto.randomUUID?.()||String(Date.now()),shipmentNo:id('SHP',state.shipments),orderNo:'',pickQty:0,packingList:'',invoiceNo:'',oqcStatus:'PENDING',shippingRelease:'BLOCKED',podNo:'',status:'DRAFT'});dirty();renderShipping()}
function renderShipping(){const financePending=state.financeApprovals.filter(x=>x.status==='PENDING').length,releaseBlocked=state.shipments.filter(x=>x.shippingRelease==='BLOCKED').length,ready=state.shipments.filter(x=>x.shippingRelease==='RELEASED'&&x.status!=='SHIPPED').length,shipped=state.shipments.filter(x=>x.status==='SHIPPED').length;$('#shippingKpis').innerHTML=[[tx('Finance pending','Finans bekliyor'),financePending],[tx('Release blocked','Çıkış engelli'),releaseBlocked],[tx('Ready','Hazır'),ready],[tx('Shipped','Sevk edildi'),shipped]].map(x=>`<div class="kpi">${x[0]}<b>${n(x[1],0)}</b></div>`).join('');$('#financeTable').innerHTML='<thead><tr><th>Approval</th><th>Type</th><th>Reference</th><th>Amount</th><th>Docs match</th><th>QC</th><th>Credit</th><th>Status</th><th>Gate</th><th></th></tr></thead><tbody>'+state.financeApprovals.map((x,i)=>`<tr data-index="${i}"><td>${input(x.approvalNo,'approvalNo')}</td><td>${selectValues(x.type,'type',['PURCHASE_PAYMENT','SALES_RELEASE'])}</td><td>${input(x.reference,'reference')}</td><td>${input(x.amount,'amount','number','min="0" step=".01"')}</td><td><input data-field="documentMatch" type="checkbox" ${x.documentMatch?'checked':''}></td><td><input data-field="qcApproved" type="checkbox" ${x.qcApproved?'checked':''}></td><td><input data-field="creditApproved" type="checkbox" ${x.creditApproved?'checked':''}></td><td>${chip(x.status)}</td><td><button class="gate-action" data-fin-action>Validate</button></td><td><button data-delete class="delete">Delete</button></td></tr>`).join('')+'</tbody>';$('#financeTable').onchange=e=>processEdit(e,state.financeApprovals,renderShipping);$('#financeTable').onclick=e=>{const row=e.target.closest('tr[data-index]');if(!row)return;const i=+row.dataset.index;if(e.target.closest('[data-delete]')){state.financeApprovals.splice(i,1);dirty();renderShipping();return}if(e.target.closest('[data-fin-action]'))validateFinance(i)};$('#shipmentTable').innerHTML='<thead><tr><th>Shipment</th><th>Sales Order</th><th>Pick Qty</th><th>Packing list</th><th>Invoice</th><th>OQC</th><th>Release</th><th>POD</th><th>Status</th><th>Gate</th><th></th></tr></thead><tbody>'+state.shipments.map((x,i)=>`<tr data-index="${i}"><td>${input(x.shipmentNo,'shipmentNo')}</td><td>${input(x.orderNo,'orderNo')}</td><td>${input(x.pickQty,'pickQty','number','min="0" step="any"')}</td><td>${input(x.packingList,'packingList')}</td><td>${input(x.invoiceNo,'invoiceNo')}</td><td>${selectValues(x.oqcStatus,'oqcStatus',['PENDING','ACCEPTED','REJECTED'])}</td><td>${chip(x.shippingRelease)}</td><td>${input(x.podNo,'podNo')}</td><td>${chip(x.status)}</td><td><button class="gate-action" data-ship-action ${x.status==='SHIPPED'?'disabled':''}>${x.shippingRelease==='RELEASED'?'Post shipment':'Check release'}</button></td><td><button data-delete class="delete">Delete</button></td></tr>`).join('')+'</tbody>';$('#shipmentTable').onchange=e=>processEdit(e,state.shipments,renderShipping);$('#shipmentTable').onclick=e=>{const row=e.target.closest('tr[data-index]');if(!row)return;const i=+row.dataset.index;if(e.target.closest('[data-delete]')){state.shipments.splice(i,1);dirty();renderShipping();return}if(e.target.closest('[data-ship-action]'))advanceShipment(i)}}
function validateFinance(i){const a=state.financeApprovals[i];a.status=a.documentMatch&&a.qcApproved&&(a.type==='PURCHASE_PAYMENT'||a.creditApproved)?'APPROVED':'BLOCKED';if(a.status==='BLOCKED')toast(tx('Blocked: document, QC and credit gates are incomplete.','Engellendi: belge, QC ve kredi kontrolleri eksik.'));dirty();renderAll()}
function advanceShipment(i){const s=state.shipments[i],o=state.salesOrders.find(x=>x.orderNo===s.orderNo),fin=state.financeApprovals.find(x=>x.type==='SALES_RELEASE'&&x.reference===s.orderNo&&x.status==='APPROVED');if(s.shippingRelease!=='RELEASED'){if(!o||o.status!=='READY_TO_SHIP'||!fin||s.oqcStatus!=='ACCEPTED'||!s.packingList||!s.invoiceNo||!(+s.pickQty>0)||+s.pickQty>+o.reservedQty){s.shippingRelease='BLOCKED';toast(tx('Blocked: reservation, finance, OQC, picking, packing list or invoice is incomplete.','Engellendi: rezervasyon, finans, OQC, toplama, paket listesi veya fatura eksik.'));dirty();renderShipping();return}s.shippingRelease='RELEASED';s.status='READY'}else{state.stock[o.sku]['WH-FG']=Math.max(0,(+state.stock[o.sku]['WH-FG']||0)-(+s.pickQty||0));state.stock[o.sku].reserved=Math.max(0,(+state.stock[o.sku].reserved||0)-(+s.pickQty||0));o.reservedQty=Math.max(0,(+o.reservedQty||0)-(+s.pickQty||0));s.status='SHIPPED';o.status=o.reservedQty?'PARTIALLY_SHIPPED':'SHIPPED'}dirty();renderAll()}

function processEdit(e,collection,rerender){const el=e.target.closest('[data-field]'),row=e.target.closest('tr[data-index]');if(!el||!row)return;const item=collection[+row.dataset.index];item[el.dataset.field]=el.type==='checkbox'?el.checked:el.dataset.number?parseLocalizedNumber(el.value):el.value;dirty();rerender()}
function processDelete(e,collection,rerender){const b=e.target.closest('[data-delete]'),row=e.target.closest('tr[data-index]');if(!b||!row)return;collection.splice(+row.dataset.index,1);dirty();rerender()}

function exchangeStatus(v){return ({ACTIVE:tx('Active','Aktif'),NEGOTIATION:tx('Negotiation','Görüşme'),SOLD:tx('Sold','Satıldı'),ARCHIVED:tx('Archived','Arşivlendi')})[v]||v}
function exchangeCondition(v){return ({NEW:tx('New / Unused','Yeni / Kullanılmamış'),GOOD:tx('Good','İyi'),INSPECT:tx('Inspection Required','Kontrol Gerekli'),EXPIRING:tx('Near Expiry','Son Kullanım Yakın')})[v]||v}
function addExchangeListing(){state.exchangeListings.unshift({id:crypto.randomUUID?.()||String(Date.now()),sku:'',description:'',category:'',qty:0,unit:'ADET',askingPrice:0,location:'Istanbul',condition:'NEW',seller:state.company||'Hamvara',contact:'',status:'ACTIVE',createdAt:new Date().toISOString().slice(0,10)});dirty();renderExchange();renderDashboard()}
function suggestExcessListings(){let added=0;for(const x of state.skus){const excess=Math.max(0,totalStock(x.code)-(+x.max||0));if(excess<=0||state.exchangeListings.some(l=>l.sku===x.code&&['ACTIVE','NEGOTIATION'].includes(l.status)))continue;state.exchangeListings.unshift({id:crypto.randomUUID?.()||x.code+'-'+Date.now(),sku:x.code,description:x.name||'',category:x.type||'',qty:excess,unit:x.unit||'ADET',askingPrice:+x.cost||0,location:'Istanbul',condition:'NEW',seller:state.company||'Hamvara',contact:'',status:'ACTIVE',createdAt:new Date().toISOString().slice(0,10),source:'AUTO_EXCESS'});added++}if(added){dirty();renderExchange();renderDashboard()}toast(added?tx(added+' excess item(s) added as draft listings.',added+' fazla stok ilan olarak eklendi.'):tx('No new excess stock found.','Yeni fazla stok bulunamadı.'))}
function renderExchange(){const el=$('#exchangeTable');if(!el)return;const q=($('#exchangeSearch')?.value||'').toLowerCase(),rows=state.exchangeListings.map((x,i)=>({x,i})).filter(o=>(o.x.sku+' '+o.x.description+' '+o.x.location+' '+o.x.seller).toLowerCase().includes(q));const active=state.exchangeListings.filter(x=>x.status==='ACTIVE').length,neg=state.exchangeListings.filter(x=>x.status==='NEGOTIATION').length,sold=state.exchangeListings.filter(x=>x.status==='SOLD').length,value=state.exchangeListings.filter(x=>x.status==='ACTIVE').reduce((s,x)=>s+(+x.qty||0)*(+x.askingPrice||0),0);$('#exchangeKpis').innerHTML=[[tx('Active Listings','Aktif İlanlar'),active],[tx('In Negotiation','Görüşmede'),neg],[tx('Sold','Satıldı'),sold],[tx('Listed Value','İlan Değeri'),n(value)+' '+esc(state.settings.currency||'TRY')]].map(x=>`<div class="kpi">${x[0]}<b>${x[1]}</b></div>`).join('');el.innerHTML=`<thead><tr><th>SKU</th><th>${tx('Description','Açıklama')}</th><th>${tx('Quantity','Miktar')}</th><th>${tx('Unit','Birim')}</th><th>${tx('Unit Price','Birim Fiyat')}</th><th>${tx('Location','Konum')}</th><th>${tx('Condition','Durum')}</th><th>${tx('Seller','Satıcı')}</th><th>${tx('Contact','İletişim')}</th><th>${tx('Listing Status','İlan Durumu')}</th><th></th></tr></thead><tbody>`+rows.map(o=>`<tr data-index="${o.i}"><td><input data-exchange="sku" list="skuOptions" value="${esc(o.x.sku)}"></td><td>${input(o.x.description,'description')}</td><td>${input(o.x.qty,'qty','number','min="0" step="0.0001"')}</td><td>${optionSelect(o.x.unit,'unit',UNITS)}</td><td>${input(o.x.askingPrice,'askingPrice','number','min="0" step="0.01"')}</td><td>${input(o.x.location,'location')}</td><td><select data-exchange="condition">${['NEW','GOOD','INSPECT','EXPIRING'].map(v=>`<option value="${v}" ${o.x.condition===v?'selected':''}>${exchangeCondition(v)}</option>`).join('')}</select></td><td>${input(o.x.seller,'seller')}</td><td>${input(o.x.contact,'contact')}</td><td><select data-exchange="status">${['ACTIVE','NEGOTIATION','SOLD','ARCHIVED'].map(v=>`<option value="${v}" ${o.x.status===v?'selected':''}>${exchangeStatus(v)}</option>`).join('')}</select></td><td><button data-exchange-delete class="delete">${tx('Delete','Sil')}</button></td></tr>`).join('')+'</tbody>';el.onchange=e=>{const row=e.target.closest('tr[data-index]');if(!row)return;const item=state.exchangeListings[+row.dataset.index],field=e.target.dataset.exchange||e.target.dataset.field;if(!field)return;item[field]=e.target.dataset.number?parseLocalizedNumber(e.target.value):e.target.value;if(field==='sku'){const x=sku(item.sku);item.description=x?.name||item.description;item.unit=x?.unit||item.unit;item.category=x?.type||item.category;item.askingPrice=item.askingPrice||(+x?.cost||0)}dirty();renderExchange();renderDashboard()};el.onclick=e=>{if(!e.target.closest('[data-exchange-delete]'))return;state.exchangeListings.splice(+e.target.closest('tr').dataset.index,1);dirty();renderExchange();renderDashboard()}}

const IMPORT_TEMPLATES={
  openingStock:{file:'Hamvara_Opening_Stock.xlsx',sheet:'Opening Stock',headers:['SKU','Description','Warehouse','Quantity','UoM','Unit Cost','Batch No','Opening Date'],sample:[['RM-001','Example raw material','WH-RM',100.5,'KG',25,'BATCH-001',new Date().toISOString().slice(0,10)]]},
  receipts:{file:'Hamvara_Inventory_Transactions.xlsx',sheet:'Inventory Transactions',headers:['Transaction Type','Date','Reference','SKU','Quantity','Warehouse','Source Warehouse','Supplier','Notes'],sample:[['GOODS_RECEIPT',new Date().toISOString().slice(0,10),'GR-00001','RM-001',25.75,'WH-RM','','Supplier A',''],['SHOP_FLOOR_TO_PRODUCT',new Date().toISOString().slice(0,10),'SF-00001','FG-001',10,'WH-FG','WH-SF','','Finished production receipt']]},
  orders:{file:'Hamvara_Orders.xlsx',sheet:'Orders',headers:['Order No','Date','Customer','Product Code','Quantity','Due Date','Priority','Notes'],sample:[['ORD-0001',new Date().toISOString().slice(0,10),'Customer A','PRD-001',100,new Date().toISOString().slice(0,10),'NORMAL','']]},
  bom:{file:'Hamvara_Product_BOM.xlsx',sheet:'Product BOM',headers:['Product Code','Component SKU','Source Warehouse','Usage Quantity'],sample:[['PRD-001','RM-001','WH-RM',0.025]]}
};
function downloadImportTemplate(type){const t=IMPORT_TEMPLATES[type];downloadWorkbook(t.file,t.sheet,t.headers,t.sample);toast(tx('Excel template downloaded.','Excel şablonu indirildi.'))}
function val(row,key){return row[key]??''}function num(row,key){return parseLocalizedNumber(val(row,key))}
function warehouseCode(value){const v=String(value||'').trim().toLowerCase();const w=state.warehouses.find(x=>x.code.toLowerCase()===v||x.name.toLowerCase()===v||warehouseName(x).toLowerCase()===v);return w?.code||''}
function isoDate(v){if(typeof v==='number'&&v>0){const d=new Date(Date.UTC(1899,11,30)+v*86400000);return d.toISOString().slice(0,10)}const s=String(v||'').trim();return /^\d{4}-\d{2}-\d{2}$/.test(s)?s:new Date().toISOString().slice(0,10)}
function validateImportRow(type,row,index){const errors=[];if(type==='openingStock'){const code=String(val(row,'SKU')).trim(),qty=num(row,'Quantity'),wh=warehouseCode(val(row,'Warehouse'));if(!code)errors.push('SKU required');if(!wh)errors.push('Invalid warehouse');if(!Number.isFinite(qty)||qty<0)errors.push('Quantity must be zero or positive');return{row,index,status:errors.length?'BLOCKED':'READY',errors,clean:{code,name:String(val(row,'Description')).trim(),warehouse:wh,qty,unit:String(val(row,'UoM')||'ADET').trim(),cost:num(row,'Unit Cost')||0,batch:String(val(row,'Batch No')).trim(),date:isoDate(val(row,'Opening Date'))}}}
  if(type==='orders'){const orderNo=String(val(row,'Order No')).trim(),productCode=String(val(row,'Product Code')).trim(),qty=num(row,'Quantity');if(!orderNo)errors.push('Order No required');if(!product(productCode))errors.push('Product not found');if(!Number.isFinite(qty)||qty<=0)errors.push('Quantity must be greater than zero');return{row,index,status:errors.length?'BLOCKED':'READY',errors,clean:{orderNo,date:isoDate(val(row,'Date')),customer:String(val(row,'Customer')).trim(),productCode,qty,due:isoDate(val(row,'Due Date')),priority:['NORMAL','URGENT','VERY_URGENT'].includes(String(val(row,'Priority')).trim().toUpperCase())?String(val(row,'Priority')).trim().toUpperCase():'NORMAL',notes:String(val(row,'Notes')).trim()}}}
  if(type==='bom'){const productCode=String(val(row,'Product Code')).trim(),component=String(val(row,'Component SKU')).trim(),wh=warehouseCode(val(row,'Source Warehouse')),qty=num(row,'Usage Quantity');if(!product(productCode))errors.push('Product not found');if(!sku(component))errors.push('Component SKU not found');if(!wh)errors.push('Invalid warehouse');if(!Number.isFinite(qty)||qty<=0)errors.push('Usage Quantity must be greater than zero');return{row,index,status:errors.length?'BLOCKED':'READY',errors,clean:{productCode,component,warehouse:wh,qty}}}
  const transaction=String(val(row,'Transaction Type')||'GOODS_RECEIPT').trim().toUpperCase(),code=String(val(row,'SKU')).trim(),qty=num(row,'Quantity'),dest=warehouseCode(val(row,'Warehouse')),source=warehouseCode(val(row,'Source Warehouse'));if(!sku(code))errors.push('SKU not found');if(!['GOODS_RECEIPT','SHOP_FLOOR_RECEIPT','FINISHED_PRODUCT_RECEIPT','SHOP_FLOOR_TO_PRODUCT','WAREHOUSE_TRANSFER'].includes(transaction))errors.push('Invalid Transaction Type');if(!Number.isFinite(qty)||qty<=0)errors.push('Quantity must be greater than zero');if(!dest)errors.push('Invalid destination warehouse');if(['SHOP_FLOOR_TO_PRODUCT','WAREHOUSE_TRANSFER'].includes(transaction)&&!source)errors.push('Invalid source warehouse');if(source&&(+state.stock[code]?.[source]||0)<qty)errors.push('Insufficient source stock');return{row,index,status:errors.length?'BLOCKED':'READY',errors,clean:{transaction,code,qty,dest,source,date:isoDate(val(row,'Date')),reference:String(val(row,'Reference')).trim(),supplier:String(val(row,'Supplier')).trim(),notes:String(val(row,'Notes')).trim()}}}
async function prepareImport(type,file){try{const rows=await readWorkbookFile(file);if(!rows.length)throw Error('Worksheet is empty');const results=rows.map((r,i)=>validateImportRow(type,r,i+2));importSession={type,results};renderImportReview()}catch(e){toast(tx('Excel import error: ','Excel içe aktarma hatası: ')+e.message)}}
function renderImportReview(){const ready=importSession.results.filter(x=>x.status==='READY').length,blocked=importSession.results.length-ready;$('#importSummary').textContent=`${ready} READY | ${blocked} BLOCKED`;$('#importReviewTable').innerHTML='<thead><tr><th>Row</th><th>Status</th><th>SKU / Product</th><th>Quantity</th><th>Warehouse</th><th>Errors</th></tr></thead><tbody>'+importSession.results.slice(0,500).map(x=>`<tr><td>${x.index}</td><td class="${x.status==='READY'?'status-ready':'status-blocked'}">${x.status}</td><td>${esc(x.clean.code||x.clean.component||x.clean.productCode||'')}</td><td>${esc(x.clean.qty??'')}</td><td>${esc(x.clean.warehouse||x.clean.dest||'')}</td><td>${esc(x.errors.join('; '))}</td></tr>`).join('')+'</tbody>';$('#postImport').disabled=!ready;$('#importReview').hidden=false}
function closeImportReview(){$('#importReview').hidden=true;importSession=null}
function postValidatedImport(){if(!importSession)return;const ready=importSession.results.filter(x=>x.status==='READY'),type=importSession.type;for(const x of ready){const c=x.clean;if(type==='openingStock'){let item=sku(c.code);if(!item){item={code:c.code,name:c.name||c.code,type:'',category:'',unit:c.unit||'ADET',cost:c.cost,warehouse:c.warehouse,supplier:'',leadTime:0,min:0,max:0,active:true};state.skus.push(item)}else{if(c.name)item.name=c.name;if(c.unit)item.unit=c.unit;if(Number.isFinite(c.cost))item.cost=c.cost}state.stock[c.code]??={};const before=+state.stock[c.code][c.warehouse]||0;state.stock[c.code][c.warehouse]=c.qty;state.receipts.unshift({id:crypto.randomUUID?.()||String(Date.now()),date:c.date,reference:'OPENING-'+c.date,sku:c.code,description:item.name,warehouse:c.warehouse,qty:c.qty,before,after:c.qty,supplier:'',notes:`Opening Balance${c.batch?' | Batch: '+c.batch:''}`,transactionType:'OPENING_BALANCE',postedAt:new Date().toISOString()})}
    else if(type==='orders')state.orders.push({id:crypto.randomUUID?.()||String(Date.now()+Math.random()),...c});
    else if(type==='bom'){state.boms[c.productCode]??=[];const existing=state.boms[c.productCode].find(l=>l.sku===c.component&&l.warehouse===c.warehouse);if(existing)existing.qty=c.qty;else if(state.boms[c.productCode].length<20)state.boms[c.productCode].push({sku:c.component,name:sku(c.component)?.name||'',warehouse:c.warehouse,qty:c.qty})}
    else if(c.transaction==='GOODS_RECEIPT'){const receiptId=crypto.randomUUID?.()||String(Date.now()+Math.random()),inspectionId=crypto.randomUUID?.()||receiptId+'-qc';queueReceiptForApproval(state,{id:receiptId,inspectionId,inspectionNo:id('IQC',state.qualityInspections),date:c.date,reference:c.reference||'IMP-'+String(state.receipts.length+1).padStart(5,'0'),sku:c.code,description:sku(c.code)?.name||'',targetWarehouse:c.dest,qty:c.qty,supplier:c.supplier,notes:c.notes,transactionType:'GOODS_RECEIPT_QUARANTINE',postedAt:new Date().toISOString()})}
    else{state.stock[c.code]??={};if(c.source)state.stock[c.code][c.source]=(+state.stock[c.code][c.source]||0)-c.qty;const before=+state.stock[c.code][c.dest]||0;state.stock[c.code][c.dest]=before+c.qty;state.receipts.unshift({id:crypto.randomUUID?.()||String(Date.now()+Math.random()),date:c.date,reference:c.reference||'IMP-'+String(state.receipts.length+1).padStart(5,'0'),sku:c.code,description:sku(c.code)?.name||'',warehouse:c.dest,sourceWarehouse:c.source,qty:c.qty,supplier:c.supplier,notes:c.notes,before,after:before+c.qty,status:'POSTED',qcStatus:'NOT_REQUIRED',managerStatus:'NOT_REQUIRED',targetWarehouse:c.dest,transactionType:c.transaction,postedAt:new Date().toISOString()})}}
  dirty();renderAll();$('#importReview').hidden=true;importSession=null;toast(tx(`${ready.length} READY row(s) posted.`,`${ready.length} READY satırı kaydedildi.`))}

function csvCell(v){return '"'+String(v??'').replaceAll('"','""')+'"'}
function exportRequirements(){const c=compute(),h=['Order','Product','SKU','Description','Warehouse','Factor','Required','Available','Shortage','Status'],rows=c.details.map(x=>[x.orderNo,x.productCode,x.sku,x.name,x.warehouse,x.factor,x.need,x.available,x.shortage,x.status]);exportText('order_requirements.csv','\uFEFF'+[h,...rows].map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv')}
async function exportText(name,text,type){if(invoke){try{const p=await invoke('export_file',{fileName:name,contents:text});toast(tx('Saved: ','Kaydedildi: ')+p);return}catch(e){toast(String(e))}}const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();URL.revokeObjectURL(a.href)}

load();
